from __future__ import annotations

from dataclasses import dataclass


APPROVAL_STAGE = "Legal Review"
ACTIVE_CARD_STATUSES = {"open", "pending"}


def _non_empty(label: str, value: str) -> None:
    if not value.strip():
        raise ValueError(f"{label} required")


@dataclass(frozen=True)
class OpportunityEvent:
    event_id: str
    opportunity_id: str
    stage: str
    revision: int
    amount_cents: int
    discount_percent: int
    region: str
    account_segment: str

    def __post_init__(self) -> None:
        _non_empty("event_id", self.event_id)
        _non_empty("opportunity_id", self.opportunity_id)
        _non_empty("stage", self.stage)
        if self.revision <= 0:
            raise ValueError("revision must be positive")
        if self.amount_cents <= 0:
            raise ValueError("amount_cents must be positive")
        if not 0 <= self.discount_percent <= 100:
            raise ValueError("discount_percent must be between 0 and 100")
        _non_empty("region", self.region)
        _non_empty("account_segment", self.account_segment)

    def pipeline_coordinates(self) -> tuple[str, str]:
        return (self.region, self.account_segment)


@dataclass(frozen=True)
class RoutingRule:
    rule_id: str
    channel_id: str
    region: str
    account_segment: str
    minimum_discount_percent: int

    def __post_init__(self) -> None:
        _non_empty("rule_id", self.rule_id)
        _non_empty("channel_id", self.channel_id)
        _non_empty("region", self.region)
        _non_empty("account_segment", self.account_segment)
        if not 0 <= self.minimum_discount_percent <= 100:
            raise ValueError("minimum_discount_percent must be between 0 and 100")

    def covers(self, region: str, segment: str) -> bool:
        return self.region == region and self.account_segment == segment


@dataclass(frozen=True)
class ApprovalCard:
    card_id: str
    opportunity_id: str
    revision: int
    channel_id: str
    status: str

    def __post_init__(self) -> None:
        _non_empty("card_id", self.card_id)
        _non_empty("opportunity_id", self.opportunity_id)
        if self.revision <= 0:
            raise ValueError("revision must be positive")
        _non_empty("channel_id", self.channel_id)
        _non_empty("status", self.status)

    def stable_business_ref(self) -> tuple[str, int]:
        return (self.opportunity_id, self.revision)


def requires_approval_stage(stage: str) -> bool:
    return stage == APPROVAL_STAGE


def is_active_card_status(status: str) -> bool:
    return status in ACTIVE_CARD_STATUSES

