from __future__ import annotations

"""Stable tuple keys for Slack approval-card idempotency checks (starter uses channel-scoped keys)."""

from alert_models import ApprovalCard, OpportunityEvent, RoutingRule


def active_card_channel_key(card: ApprovalCard) -> tuple[str, int, str]:
    """Key that treats each Slack channel separately (lets overlapping routes fan out)."""
    return (card.opportunity_id, card.revision, card.channel_id)


def event_channel_fanout_key(event: OpportunityEvent, channel_id: str) -> tuple[str, int, str]:
    """Candidate key for a would-be card in a specific channel."""
    return (event.opportunity_id, event.revision, channel_id)


def revision_boundary_key(opportunity_id: str, revision: int) -> tuple[str, int]:
    """Business idempotency boundary described in product requirements (opp + revision only)."""
    return (opportunity_id, revision)


def active_revision_keys(cards: list[ApprovalCard], active_statuses: set[str]) -> set[tuple[str, int]]:
    return {
        revision_boundary_key(card.opportunity_id, card.revision)
        for card in cards
        if card.status in active_statuses
    }


def rule_rank(rule: RoutingRule, rules_list: list[RoutingRule]) -> int:
    try:
        return rules_list.index(rule)
    except ValueError:
        return len(rules_list)


def format_rule_route(rule: RoutingRule) -> str:
    return f"{rule.rule_id}:{rule.region}:{rule.account_segment}->{rule.channel_id}"


def describe_discount_gate(event: OpportunityEvent, rule: RoutingRule) -> str:
    return (
        f"discount {event.discount_percent}% vs rule floor {rule.minimum_discount_percent}% "
        f"for {rule.rule_id}"
    )


def audit_channel_suffix(channel_id: str | None) -> str:
    return "all_channels" if channel_id is None else channel_id


def opportunity_revision_label(event: OpportunityEvent) -> str:
    return f"{event.opportunity_id}@{event.revision}"


def sorted_rule_matches(matches: list[RoutingRule], routing_rules: list[RoutingRule]) -> list[RoutingRule]:
    return sorted(matches, key=lambda rule: rule_rank(rule, routing_rules))


def channel_list_for_matches(matches: list[RoutingRule]) -> list[str]:
    return [rule.channel_id for rule in matches]


def partition_events_by_stage(events: list[OpportunityEvent], approval_stage: str) -> tuple[list[OpportunityEvent], list[OpportunityEvent]]:
    qualifying = [row for row in events if row.stage == approval_stage]
    other = [row for row in events if row.stage != approval_stage]
    return qualifying, other


def revision_open_card_count(cards: list[ApprovalCard], opportunity_id: str, revision: int, active_statuses: set[str]) -> int:
    return sum(
        1
        for card in cards
        if card.opportunity_id == opportunity_id
        and card.revision == revision
        and card.status in active_statuses
    )


def max_channels_per_revision_limit(default_cap: int = 1) -> int:
    """Single active approval card per revision is the reconciliation target ops teams expect."""
    if default_cap <= 0:
        raise ValueError("default cap must be positive")
    return default_cap


def explain_overlap_hypothesis(channel_ids: list[str]) -> str:
    distinct = sorted(set(channel_ids))
    if len(distinct) < 2:
        return "single_route"
    return f"overlapping_channels:{','.join(distinct)}"

